const API_BASE_URL = (process.env.REACT_APP_API_URL || '').replace(/\/$/, '');

async function request(path, { token, ...options } = {}) {
  if (!API_BASE_URL) {
    throw new Error('Account features are unavailable because REACT_APP_API_URL is not configured.');
  }

  let response;
  try {
    response = await fetch(`${API_BASE_URL}${path}`, {
      ...options,
      headers: {
        ...(options.body ? { 'Content-Type': 'application/json' } : {}),
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
        ...options.headers,
      },
    });
  } catch {
    throw new Error('Could not reach the account service. Please try again later.');
  }

  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(data.error || data.message || 'The request could not be completed.');
  }
  return data;
}

export const api = {
  register: (credentials) => request('/auth/register', {
    method: 'POST',
    body: JSON.stringify(credentials),
  }),
  login: (credentials) => request('/auth/login', {
    method: 'POST',
    body: JSON.stringify(credentials),
  }),
  me: (token) => request('/auth/me', { token }),
  games: (token) => request('/games', { token }),
  saveGame: (token, game) => request('/games', {
    method: 'POST',
    token,
    body: JSON.stringify(game),
  }),
};
